From 81a0a35e50c26bf78f788c37ee8efc783240371d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:33:39 +0100
Subject: [PATCH] applets/keyboardindicator: allow showing the icon when a lock
 key is off

Many people keep Num Lock on all the time and only want to notice when
it is off, but the widget could only show itself while a lock key was
on. Each lock key now has a combobox that also offers this option.

BUG: 447027
---
 .../keyboardindicator/configAppearance.qml    | 52 ++++++++++++-------
 applets/keyboardindicator/main.qml            | 25 ++++++---
 applets/keyboardindicator/main.xml            |  3 ++
 3 files changed, 54 insertions(+), 26 deletions(-)

diff --git a/applets/keyboardindicator/configAppearance.qml b/applets/keyboardindicator/configAppearance.qml
index 192ff5e3e..5115ebafa 100644
--- a/applets/keyboardindicator/configAppearance.qml
+++ b/applets/keyboardindicator/configAppearance.qml
@@ -16,16 +16,31 @@ KCM.SimpleKCM {
     signal configurationChanged()

     property var cfg_key: []
+    property var cfg_keyDeactivated: []

-    function toggle(name, checked) {
-        const index = cfg_key.indexOf(name);
+    readonly property list<string> modes: [
+        i18nc("@item:inlistbox show keyboard indicator for this lock key", "Never show"),
+        i18nc("@item:inlistbox show keyboard indicator for this lock key", "Show when activated"),
+        i18nc("@item:inlistbox show keyboard indicator for this lock key", "Show when deactivated"),
+    ]

-        if (checked) {
-            if (index < 0) {
-                cfg_key.push(name);
-            }
-        } else if (index >= 0) {
-            cfg_key.splice(index, 1);
+    function mode(name) {
+        if (cfg_key.indexOf(name) >= 0) {
+            return 1;
+        } else if (cfg_keyDeactivated.indexOf(name) >= 0) {
+            return 2;
+        }
+        return 0;
+    }
+
+    function setMode(name, mode) {
+        cfg_key = cfg_key.filter(key => key !== name);
+        cfg_keyDeactivated = cfg_keyDeactivated.filter(key => key !== name);
+
+        if (mode === 1) {
+            cfg_key = cfg_key.concat(name);
+        } else if (mode === 2) {
+            cfg_keyDeactivated = cfg_keyDeactivated.concat(name);
         }

         configurationChanged();
@@ -33,19 +48,18 @@ KCM.SimpleKCM {

     Kirigami.FormLayout {

-        Controls.CheckBox {
-            Kirigami.FormData.label: i18nc("@label show keyboard indicator when Caps Lock or Num Lock is activated", "Show when activated:")
-            readonly property string name: "Caps Lock"
-            checked: root.cfg_key.indexOf(name) >= 0
-            text: i18nc("@option:check", "Caps Lock")
-            onToggled: root.toggle(name, checked)
+        Controls.ComboBox {
+            Kirigami.FormData.label: i18nc("@label:listbox", "Caps Lock:")
+            model: root.modes
+            currentIndex: root.mode("Caps Lock")
+            onActivated: index => root.setMode("Caps Lock", index)
         }

-        Controls.CheckBox {
-            readonly property string name: "Num Lock"
-            checked: root.cfg_key.indexOf(name) >= 0
-            text: i18nc("@option:check", "Num Lock")
-            onToggled: root.toggle(name, checked)
+        Controls.ComboBox {
+            Kirigami.FormData.label: i18nc("@label:listbox", "Num Lock:")
+            model: root.modes
+            currentIndex: root.mode("Num Lock")
+            onActivated: index => root.setMode("Num Lock", index)
         }
     }
 }
diff --git a/applets/keyboardindicator/main.qml b/applets/keyboardindicator/main.qml
index cbbafdeb5..34ac60b7c 100644
--- a/applets/keyboardindicator/main.qml
+++ b/applets/keyboardindicator/main.qml
@@ -18,8 +18,11 @@ import org.kde.plasma.extras as PlasmaExtras
 PlasmoidItem {
     id: root

-    readonly property KeyboardIndicator.KeyState capsLockState: Plasmoid.configuration.key.includes("Caps Lock") ? kiComponent.createObject(null, {key: Qt.Key_CapsLock}) as KeyboardIndicator.KeyState : null
-    readonly property KeyboardIndicator.KeyState numLockState: Plasmoid.configuration.key.includes("Num Lock") ? kiComponent.createObject(null, {key: Qt.Key_NumLock})  as KeyboardIndicator.KeyState : null
+    readonly property bool capsLockInverted: Plasmoid.configuration.keyDeactivated.includes("Caps Lock")
+    readonly property bool numLockInverted: Plasmoid.configuration.keyDeactivated.includes("Num Lock")
+
+    readonly property KeyboardIndicator.KeyState capsLockState: Plasmoid.configuration.key.includes("Caps Lock") || capsLockInverted ? kiComponent.createObject(null, {key: Qt.Key_CapsLock}) as KeyboardIndicator.KeyState : null
+    readonly property KeyboardIndicator.KeyState numLockState: Plasmoid.configuration.key.includes("Num Lock") || numLockInverted ? kiComponent.createObject(null, {key: Qt.Key_NumLock})  as KeyboardIndicator.KeyState : null

     readonly property KeyboardIndicator.KeyState altState: kiComponent.createObject(null, {key: Qt.Key_Alt}) as KeyboardIndicator.KeyState
     readonly property KeyboardIndicator.KeyState shiftState: kiComponent.createObject(null, {key: Qt.Key_Shift}) as KeyboardIndicator.KeyState
@@ -31,15 +34,17 @@ PlasmoidItem {
         var ret = anyModifierActive

         if (capsLockState) {
-            ret = ret || capsLockState.locked
+            ret = ret || capsLockState.locked !== capsLockInverted
         }

         if (numLockState) {
-            ret = ret || numLockState.locked
+            ret = ret || numLockState.locked !== numLockInverted
         }
         return ret
     }

+    readonly property bool anyLocked: anyModifierActive || capsLockState?.locked || numLockState?.locked || false
+
     readonly property bool anyModifierActive: altState.latched || altState.locked || shiftState.latched || shiftState.locked || controlState.latched || controlState.locked || metaState.latched || metaState.locked || altGrState.latched || altGrState.locked

     Plasmoid.icon: {
@@ -56,7 +61,7 @@ PlasmoidItem {
             return "input-caps-on-symbolic";
         } else if (numLockState?.locked) {
             return "input-num-on-symbolic";
-        } else if (numLockState && !capsLockState) {
+        } else if (numLockState && (!capsLockState || (numLockInverted && !capsLockInverted))) {
             return "input-num-on-symbolic";
         } else {
             return "input-caps-on-symbolic";
@@ -89,7 +94,7 @@ PlasmoidItem {
             anchors.fill: parent
             source: Plasmoid.icon
             active: compactMouse.containsMouse
-            enabled: root.anyActive
+            enabled: root.anyLocked
         }
     }

@@ -100,7 +105,7 @@ PlasmoidItem {
         PlasmaExtras.PlaceholderMessage {
             anchors.centerIn: parent
             width: parent.width - (Kirigami.Units.gridUnit * 4)
-            iconName: root.anyActive ? Plasmoid.icon : ""
+            iconName: root.anyLocked ? Plasmoid.icon : ""
             text: root.toolTipSubText
         }
     }
@@ -149,6 +154,12 @@ PlasmoidItem {
         if (root.numLockState?.locked) {
             text.push(i18nc("@info:tooltip widget subtitle, Num Lock on", "Num Lock activated"));
         }
+        if (root.capsLockInverted && !root.capsLockState.locked) {
+            text.push(i18nc("@info:tooltip widget subtitle, Caps Lock off", "Caps Lock deactivated"));
+        }
+        if (root.numLockInverted && !root.numLockState.locked) {
+            text.push(i18nc("@info:tooltip widget subtitle, Num Lock off", "Num Lock deactivated"));
+        }
         if (text.length > 0) {
             // Not using KUIT markup for these newline characters because those
             // get translated into HTML, and this text is displayed in the applet's
diff --git a/applets/keyboardindicator/main.xml b/applets/keyboardindicator/main.xml
index 19f7cf1b5..318227ee2 100644
--- a/applets/keyboardindicator/main.xml
+++ b/applets/keyboardindicator/main.xml
@@ -9,6 +9,9 @@
     <entry name="key" type="StringList">
       <default>Caps Lock</default>
     </entry>
+    <entry name="keyDeactivated" type="StringList">
+      <default></default>
+    </entry>
   </group>

 </kcfg>
-- 
